// NewStore creates a new parameter store
func NewStore(params types.Params) *Store {
	return &Store{
		params: params,
	}
}

// GetParams returns the current parameters
func (s *Store) GetParams() types.Params {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.params
}

