func unwrapSDKContextSafe(ctx context.Context) (sdk.Context, bool) {
	var (
		sdkCtx sdk.Context
		ok     = true
	)
	defer func() {
		if r := recover(); r != nil {
			ok = false
		}
	}()
	sdkCtx = sdk.UnwrapSDKContext(ctx)
	return sdkCtx, ok
}

